const item = $input.item.json;

// 1) Neutraliza as tags do delimitador, se vierem dentro do e-mail
const limpaTags = (t) => String(t || '').replace(/<\s*\/?\s*email_reportado\s*>/gi, '');

let corpo = limpaTags(item.corpo);
const assuntoBruto = limpaTags(item.assunto);
const remetenteBruto = limpaTags(item.remetente);
const linkCampo = String(item.link || '').trim();

// 2) Limita o tamanho do corpo
const LIMITE_CORPO = 4000;
const corpoTruncado = corpo.length > LIMITE_CORPO;
if (corpoTruncado) corpo = corpo.slice(0, LIMITE_CORPO);

// 3) Extrai URLs (campo Link + corpo), sem duplicatas
const regexUrl = /https?:\/\/[^\s<>"'\])]+/gi;
const limpaFim = (u) => u.replace(/[.,;:!?]+$/, '');
const encontradas = [];
const adiciona = (u) => {
  const limpa = limpaFim(u);
  if (limpa && !encontradas.includes(limpa)) encontradas.push(limpa);
};
if (linkCampo) (linkCampo.match(regexUrl) || [linkCampo]).forEach(adiciona);
(corpo.match(regexUrl) || []).forEach(adiciona);

// 4) Troca as URLs no corpo por marcadores (as mais longas primeiro)
let corpoIa = corpo;
[...encontradas.keys()]
  .sort((a, b) => encontradas[b].length - encontradas[a].length)
  .forEach((i) => {
    corpoIa = corpoIa.split(encontradas[i]).join(`[URL_${i + 1}]`);
  });

// 5) Domínio de cada URL (só as 3 primeiras são analisadas)
const hostDe = (u) => {
  const m = String(u).match(/^(?:https?:\/\/)?(?:[^@\/?#]*@)?([^\/?#:]+)/i);
  return m ? m[1].toLowerCase() : '';
};
const urlsAnalisadas = encontradas.slice(0, 3).map((u, i) => ({
  marcador: `URL_${i + 1}`,
  url: u,
  dominio: hostDe(u),
}));

// 6) Domínio do remetente
const extraiDominio = (r) => {
  const s = r.trim().toLowerCase();
  const comArroba = s.match(/@([a-z0-9.-]+\.[a-z]{2,})/);
  if (comArroba) return comArroba[1];
  const soDominio = s.match(/^[a-z0-9.-]+\.[a-z]{2,}$/);
  return soDominio ? soDominio[0] : '';
};
const remetenteDominio = extraiDominio(remetenteBruto);

// 7) Mascara dados pessoais (guarda só contagens)
const contagem = { cnpj: 0, cartao: 0, cpf: 0, email: 0, telefone: 0 };
const mascara = (texto) => {
  const troca = (re, rotulo, chave) => {
    texto = texto.replace(re, () => { contagem[chave]++; return rotulo; });
  };
  troca(/\b\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}\b/g, '[CNPJ]', 'cnpj');
  troca(/\b(?:\d[ -]?){13,16}\b/g, '[CARTAO]', 'cartao');
  troca(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, '[CPF]', 'cpf');
  troca(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[EMAIL]', 'email');
  troca(/(?:\+?55\s?)?\(?\d{2}\)?\s?9?\d{4}-\d{4}/g, '[TELEFONE]', 'telefone');
  return texto;
};

return {
  json: {
    inicio_ms: Date.now(),
    submission_id: item.submission_id,
    event_id: item.event_id,
    recebido_em: item.recebido_em,
    email_colaborador: item.email_colaborador,
    remetente_dominio: remetenteDominio,
    assunto_ia: mascara(assuntoBruto),
    corpo_ia: mascara(corpoIa),
    urls_analisadas: urlsAnalisadas,
    urls_total: encontradas.length,
    urls_nao_analisadas: Math.max(0, encontradas.length - 3),
    corpo_truncado: corpoTruncado,
    mascaramento: contagem,
  },
};

const LIMIAR_MALICIOSO = 2;

const base = $('Preparar dados').first().json;
const urls = base.urls_analisadas || [];
const entradas = $input.all();

const reputacao = urls.map((u, i) => {
  const r = (entradas[i] || {}).json || {};
  const stats = r.data && r.data.attributes && r.data.attributes.last_analysis_stats;
  if (stats) {
    return {
      marcador: u.marcador,
      dominio: u.dominio,
      status: 'ok',
      malicious: stats.malicious || 0,
      suspicious: stats.suspicious || 0,
      harmless: stats.harmless || 0,
      undetected: stats.undetected || 0,
    };
  }
  const codigo = Number((r.error && r.error.status) || (r.details && r.details.httpCode) || 0);
  return {
    marcador: u.marcador,
    dominio: u.dominio,
    status: codigo === 400 ? 'nao_verificavel' : 'indisponivel',
    codigo_http: codigo || null,
  };
});

const descreve = (r) => {
  if (r.status === 'ok') {
    return `${r.marcador} (${r.dominio}): ${r.malicious} malicioso, ${r.suspicious} suspeito, ${r.harmless} inofensivo`;
  }
  if (r.status === 'nao_verificavel') return `${r.marcador} (${r.dominio}): domínio não verificável`;
  return `${r.marcador} (${r.dominio}): indisponível`;
};

const okCount = reputacao.filter((r) => r.status === 'ok').length;
let reputacao_status = 'sem_urls';
if (urls.length > 0) {
  reputacao_status = okCount === urls.length ? 'ok' : okCount === 0 ? 'indisponivel' : 'parcial';
}

return {
  json: {
    ...base,
    reputacao,
    reputacao_texto: urls.length === 0 ? 'nenhuma URL' : reputacao.map(descreve).join('; '),
    reputacao_status,
    url_maliciosa: reputacao.some((r) => r.status === 'ok' && r.malicious >= LIMIAR_MALICIOSO),
    limiar_malicioso: LIMIAR_MALICIOSO,
  },
};

const base = $('Resumir reputação').first().json;
const entrada = ($input.first() || {}).json || {};

const CLASSES = ['phishing', 'suspeito', 'legitimo', 'indeterminado'];
const RISCOS = ['alto', 'medio', 'baixo'];

const falha = (motivo) => ({
  classificacao: 'indeterminado',
  risco: 'medio',
  indicadores: [],
  justificativa: 'Resposta da IA ausente ou em formato inválido; caso encaminhado para revisão humana.',
  confianca: 0,
  acao_recomendada: 'Revisão humana.',
  _motivo: motivo,
});

const texto = (v, max) => String(v == null ? '' : v).slice(0, max);

let ia;
if (entrada.error) {
  ia = falha('erro_gemini');
} else {
  const partes = (entrada.content && entrada.content.parts) || [];
  const bruto = (partes.find((p) => p && typeof p.text === 'string') || {}).text;
  if (!bruto) {
    ia = falha('sem_texto');
  } else {
    const limpo = bruto.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
    let obj = null;
    try { obj = JSON.parse(limpo); } catch (e) { obj = null; }
    if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
      ia = falha('json_invalido');
    } else {
      const conf = Number(obj.confianca);
      const classeOk = CLASSES.includes(obj.classificacao);
      const riscoOk = RISCOS.includes(obj.risco);
      const confOk = Number.isFinite(conf) && conf >= 0 && conf <= 1;
      if (!classeOk || !riscoOk || !confOk) {
        ia = falha('campos_invalidos');
      } else {
        ia = {
          classificacao: obj.classificacao,
          risco: obj.risco,
          indicadores: (Array.isArray(obj.indicadores) ? obj.indicadores : [])
            .slice(0, 8).map((i) => texto(i, 200)),
          justificativa: texto(obj.justificativa, 500),
          confianca: conf,
          acao_recomendada: texto(obj.acao_recomendada, 300),
        };
      }
    }
  }
}

const motivo = ia._motivo || null;
delete ia._motivo;

return {
  json: {
    ...base,
    ia,
    ia_status: motivo ? 'falha' : 'ok',
    ia_motivo: motivo,
  },
};

const d = $input.item.json;
const ordem = { baixo: 0, medio: 1, alto: 2 };
let risco = d.ia.risco;
const regras = [];

const sobe = (para, regra) => {
  if (ordem[para] > ordem[risco]) {
    risco = para;
    regras.push(regra);
  }
};

if (d.url_maliciosa) sobe('alto', 'url_maliciosa');
if (d.ia_status === 'falha') sobe('medio', 'ia_falhou');
if (d.ia.classificacao !== 'legitimo') sobe('medio', 'classificacao_nao_legitima');
if (d.urls_total > 0 && d.reputacao_status !== 'ok') sobe('medio', 'reputacao_incompleta');
if (d.urls_nao_analisadas > 0) sobe('medio', 'urls_nao_analisadas');

const acao = risco === 'alto' ? 'alerta_telegram'
  : risco === 'medio' ? 'fila_revisao'
  : 'resposta_automatica';

return {
  json: {
    ...d,
    risco_ia: d.ia.risco,
    risco_final: risco,
    classificacao_final: d.ia.classificacao,
    regras_aplicadas: regras,
    divergencia_ia_reputacao:
      d.url_maliciosa && ['legitimo', 'indeterminado'].includes(d.ia.classificacao),
    acao,
  },
};

const d = $input.item.json;
const semQuery = (u) => String(u || '').split(/[?#]/)[0];

const statusPorAcao = {
  alerta_telegram: 'aguardando_validacao',
  fila_revisao: 'revisao',
  resposta_automatica: 'novo',
};

return {
  json: {
    execucao_id: String($execution.id || ''),
    submission_id: d.submission_id,
    dominio_remetente: d.remetente_dominio || null,
    assunto: d.assunto_ia,
    urls: (d.urls_analisadas || []).map((u) => ({
      marcador: u.marcador,
      url: semQuery(u.url),
      dominio: u.dominio,
    })),
    reputacao: d.reputacao,
    classificacao: d.classificacao_final,
    risco: d.risco_final,
    risco_ia: d.risco_ia,
    indicadores: d.ia.indicadores,
    justificativa: d.ia.justificativa,
    confianca: d.ia.confianca,
    acao_recomendada: d.ia.acao_recomendada,
    regras_aplicadas: d.regras_aplicadas,
    divergencia_ia_reputacao: d.divergencia_ia_reputacao,
    status: statusPorAcao[d.acao] || 'novo',
  },
};

const base = $('Regra híbrida').first().json;
const gravado = $('Gravar incidente').first().json;

return [{ json: { ...base, incidente_id: gravado.id } }];

// Troque pelo nome do modelo EXATAMENTE como aparece no nó "Classificar com Gemini"
const MODELO_GEMINI = 'gemini-3-flash-preview';

const d = $('Regra híbrida').first().json;
const execucao_id = String($execution.id || '');
const duracao = d.inicio_ms ? Date.now() - d.inicio_ms : null;
const linhas = [];

if (d.urls_total > 0) {
  const ok = d.reputacao_status === 'ok';
  linhas.push({
    execucao_id,
    etapa: 'virustotal',
    status: ok ? 'sucesso' : 'fallback',
    duracao_ms: null,
    erro: ok ? null : d.reputacao
      .filter((r) => r.status !== 'ok')
      .map((r) => `${r.status}:${r.codigo_http || 'sem_codigo'}`)
      .join(','),
    modelo: null,
    tokens: null,
  });
}

linhas.push({
  execucao_id,
  etapa: 'gemini',
  status: d.ia_status === 'ok' ? 'sucesso' : 'fallback',
  duracao_ms: null,
  erro: d.ia_status === 'ok' ? null : d.ia_motivo,
  modelo: MODELO_GEMINI,
  tokens: null,
});

const houveFallback = linhas.some((l) => l.status === 'fallback');
linhas.push({
  execucao_id,
  etapa: 'fluxo',
  status: houveFallback ? 'fallback' : 'sucesso',
  duracao_ms: duracao,
  erro: null,
  modelo: null,
  tokens: null,
});

return linhas.map((l) => ({ json: l }));

const d = $input.item.json;

// Remove caracteres que o Telegram pode interpretar como formatação
const limpa = (s) => String(s == null ? '' : s).replace(/[*_`\[\]~<>\\]/g, ' ').replace(/\s+/g, ' ').trim();
const defang = (s) => limpa(s).replace(/\./g, '(.)');

const risco = d.risco_ia === d.risco_final
  ? d.risco_final
  : `${d.risco_ia} (IA) -> ${d.risco_final} (regra)`;

const indicadores = (d.ia.indicadores || []).map((i) => `- ${limpa(i)}`).join('\n') || '- (nenhum)';
const dominiosUrl = (d.urls_analisadas || []).map((u) => defang(u.dominio)).join(', ') || 'nenhuma';

const partes = [
  'ALERTA: e-mail reportado com risco alto',
  '',
  `Classificação da IA: ${limpa(d.classificacao_final)}`,
  `Risco: ${limpa(risco)}`,
  `Confiança informada pela IA: ${limpa(d.ia.confianca)}`,
  `Remetente (domínio): ${defang(d.remetente_dominio) || 'não identificado'}`,
  `Assunto: ${limpa(d.assunto_ia)}`,
  `URLs (domínios): ${dominiosUrl}`,
  `Reputação: ${defang(d.reputacao_texto)}`,
];

if (d.divergencia_ia_reputacao) {
  partes.push('', 'ATENÇÃO: a IA não classificou como phishing, mas a reputação indicou URL maliciosa.');
}

partes.push(
  '',
  'Indicadores:',
  indicadores,
  '',
  `Justificativa: ${limpa(d.ia.justificativa)}`,
  `Ação recomendada: ${limpa(d.ia.acao_recomendada)}`,
  '',
  `Incidente: ${String(d.incidente_id || '').slice(0, 8)}`
);

return { json: { ...d, texto_alerta: partes.join('\n').slice(0, 3500) } };

const r = $input.item.json;
const incidente_id = $('Reunir dados').first().json.incidente_id;
const aprovado = r.data && r.data.approved;

let status;
let decisao_humana;
if (aprovado === true) {
  status = 'confirmado';
  decisao_humana = 'confirmado';
} else if (aprovado === false) {
  status = 'falso_positivo';
  decisao_humana = 'falso_positivo';
} else {
  status = 'aguardando_validacao';
  decisao_humana = 'sem_resposta';
}

return { json: { incidente_id, status, decisao_humana } };

const d = $input.item.json;

return {
  json: {
    execucao_id: String($execution.id || ''),
    etapa: 'roteamento',
    status: 'erro',
    duracao_ms: null,
    erro: 'acao_inesperada:' + String(d.acao || 'vazio').slice(0, 40),
    modelo: null,
    tokens: null,
  },
};

const d = $input.item.json;
const obrigatorios = ['remetente', 'assunto', 'corpo', 'email_colaborador'];
const ausentes = obrigatorios.filter((k) => String(d[k] || '').trim() === '');

return {
  json: {
    execucao_id: String($execution.id || ''),
    etapa: 'validacao',
    status: 'fallback',
    duracao_ms: null,
    erro: 'campos_ausentes:' + ausentes.join(','),
    modelo: null,
    tokens: null,
  },
};

const d = $input.first().json;
const email = String(d.email_colaborador || '').trim();
const valido = email.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

if (!valido) return [];

return [{
  json: {
    para: email,
    assunto: 'Recebemos o seu reporte de e-mail',
    mensagem:
      'Olá,\n\n' +
      'Obrigado por reportar. A análise automática não encontrou indícios de risco no e-mail enviado. ' +
      'Essa análise pode errar: se algo parecer estranho, não clique em links nem informe dados, e procure a equipe de segurança.\n\n' +
      'Mensagem automática da triagem de e-mails suspeitos (projeto fictício de estudo).',
  },
}];
